-- =====================================================================
-- 0049 · Persistent notifications and staff messaging
-- ---------------------------------------------------------------------
-- Notifications are generated by trusted database triggers. Chat reads
-- and writes are limited by conversation membership; direct conversations
-- may cross clinics, while each clinic has one automatically maintained
-- group conversation. Chat is for staff coordination, not patient data.
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.app_notifications (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    recipient_id uuid NOT NULL REFERENCES public.staff_profiles(id) ON DELETE CASCADE,
    kind         text NOT NULL CHECK (kind IN (
        'access_request', 'access_decision', 'chat_message',
        'ticket_new', 'ticket_message', 'ticket_status'
    )),
    title        text NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
    body         text NOT NULL DEFAULT '' CHECK (length(body) <= 300),
    target_url   text NOT NULL DEFAULT '',
    source_id    uuid,
    created_at   timestamptz NOT NULL DEFAULT now(),
    read_at      timestamptz
);

CREATE INDEX IF NOT EXISTS idx_app_notifications_recipient
    ON public.app_notifications (recipient_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_notifications_unread
    ON public.app_notifications (recipient_id, created_at DESC)
    WHERE read_at IS NULL;

ALTER TABLE public.app_notifications ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS app_notifications_select_own ON public.app_notifications;
CREATE POLICY app_notifications_select_own ON public.app_notifications
    FOR SELECT TO authenticated
    USING (
        recipient_id = public.ent_auth_uid()
        AND EXISTS (
            SELECT 1 FROM public.staff_profiles p
             WHERE p.id = public.ent_auth_uid() AND p.is_active
        )
    );

CREATE TABLE IF NOT EXISTS public.staff_conversations (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    kind           text NOT NULL CHECK (kind IN ('direct', 'clinic')),
    clinic_id      uuid REFERENCES public.clinics(id) ON DELETE CASCADE,
    direct_user_a  uuid REFERENCES public.staff_profiles(id) ON DELETE CASCADE,
    direct_user_b  uuid REFERENCES public.staff_profiles(id) ON DELETE CASCADE,
    created_by     uuid REFERENCES public.staff_profiles(id) ON DELETE SET NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    last_message_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT staff_conversations_shape CHECK (
        (kind = 'clinic' AND clinic_id IS NOT NULL
            AND direct_user_a IS NULL AND direct_user_b IS NULL)
        OR
        (kind = 'direct' AND clinic_id IS NULL
            AND direct_user_a IS NOT NULL AND direct_user_b IS NOT NULL
            AND direct_user_a < direct_user_b)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_staff_clinic_conversation
    ON public.staff_conversations (clinic_id)
    WHERE kind = 'clinic';
CREATE UNIQUE INDEX IF NOT EXISTS uq_staff_direct_conversation
    ON public.staff_conversations (direct_user_a, direct_user_b)
    WHERE kind = 'direct';

CREATE TABLE IF NOT EXISTS public.staff_conversation_members (
    conversation_id uuid NOT NULL REFERENCES public.staff_conversations(id) ON DELETE CASCADE,
    user_id         uuid NOT NULL REFERENCES public.staff_profiles(id) ON DELETE CASCADE,
    joined_at       timestamptz NOT NULL DEFAULT now(),
    last_read_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (conversation_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_staff_conversation_members_user
    ON public.staff_conversation_members (user_id, conversation_id);

CREATE TABLE IF NOT EXISTS public.staff_chat_messages (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id uuid NOT NULL REFERENCES public.staff_conversations(id) ON DELETE CASCADE,
    sender_id       uuid REFERENCES public.staff_profiles(id) ON DELETE SET NULL,
    sender_name     text NOT NULL DEFAULT '',
    body            text NOT NULL CHECK (length(btrim(body)) BETWEEN 1 AND 2000),
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_staff_chat_messages_thread
    ON public.staff_chat_messages (conversation_id, created_at DESC);

ALTER TABLE public.staff_conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_conversation_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_chat_messages ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS staff_conversation_members_select_own ON public.staff_conversation_members;
CREATE POLICY staff_conversation_members_select_own ON public.staff_conversation_members
    FOR SELECT TO authenticated
    USING (
        user_id = public.ent_auth_uid()
        AND EXISTS (
            SELECT 1 FROM public.staff_profiles p
             WHERE p.id = public.ent_auth_uid() AND p.is_active
        )
    );

DROP POLICY IF EXISTS staff_conversations_select_member ON public.staff_conversations;
CREATE POLICY staff_conversations_select_member ON public.staff_conversations
    FOR SELECT TO authenticated
    USING (
        EXISTS (
            SELECT 1
              FROM public.staff_conversation_members m
              JOIN public.staff_profiles p ON p.id = m.user_id AND p.is_active
             WHERE m.conversation_id = staff_conversations.id
               AND m.user_id = public.ent_auth_uid()
        )
    );

DROP POLICY IF EXISTS staff_chat_messages_select_member ON public.staff_chat_messages;
CREATE POLICY staff_chat_messages_select_member ON public.staff_chat_messages
    FOR SELECT TO authenticated
    USING (
        EXISTS (
            SELECT 1
              FROM public.staff_conversation_members m
              JOIN public.staff_profiles p ON p.id = m.user_id AND p.is_active
             WHERE m.conversation_id = staff_chat_messages.conversation_id
               AND m.user_id = public.ent_auth_uid()
        )
    );

DROP POLICY IF EXISTS staff_chat_messages_insert_member ON public.staff_chat_messages;
CREATE POLICY staff_chat_messages_insert_member ON public.staff_chat_messages
    FOR INSERT TO authenticated
    WITH CHECK (
        sender_id = public.ent_auth_uid()
        AND EXISTS (
            SELECT 1
              FROM public.staff_conversation_members m
              JOIN public.staff_profiles p ON p.id = m.user_id AND p.is_active
             WHERE m.conversation_id = staff_chat_messages.conversation_id
               AND m.user_id = public.ent_auth_uid()
        )
    );

-- Show active staff immediately, including profiles without a clinic_id.
-- Non-empty searches filter by name; usernames/contact details stay private.
CREATE OR REPLACE FUNCTION public.ent_search_chat_staff(p_query text)
RETURNS TABLE (user_id uuid, full_name text, role_name text, clinic_name text)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT p.id,
           coalesce(nullif(btrim(p.full_name), ''), 'Clinic staff'),
           p.role::text,
           coalesce(nullif(btrim(c.name), ''), c.code, 'Unassigned clinic')
      FROM public.staff_profiles me
      JOIN public.staff_profiles p ON p.is_active AND p.id <> me.id
      LEFT JOIN public.clinics c ON c.id = p.clinic_id
     WHERE me.id = public.ent_auth_uid()
       AND me.is_active
       AND (
            nullif(btrim(coalesce(p_query, '')), '') IS NULL
            OR p.full_name ILIKE '%' || btrim(p_query) || '%'
       )
     ORDER BY lower(coalesce(p.full_name, '')), lower(coalesce(c.name, c.code, ''))
     LIMIT 50;
$$;

CREATE OR REPLACE FUNCTION public.ent_chat_staff_directory(p_query text DEFAULT NULL)
RETURNS TABLE (
    user_id uuid,
    full_name text,
    role_name text,
    clinic_name text,
    last_seen_at timestamptz
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT p.id,
           coalesce(nullif(btrim(p.full_name), ''), 'Clinic staff'),
           p.role::text,
           coalesce(nullif(btrim(c.name), ''), c.code, 'Unassigned clinic'),
           max(up.seen_at)
      FROM public.staff_profiles me
      JOIN public.staff_profiles p ON p.is_active AND p.id <> me.id
      LEFT JOIN public.clinics c ON c.id = p.clinic_id
      LEFT JOIN public.user_presence up ON up.user_id = p.id
     WHERE me.id = public.ent_auth_uid()
       AND me.is_active
       AND (
            nullif(btrim(coalesce(p_query, '')), '') IS NULL
            OR p.full_name ILIKE '%' || btrim(p_query) || '%'
       )
     GROUP BY p.id, p.full_name, p.role, c.name, c.code
     ORDER BY lower(coalesce(p.full_name, '')), lower(coalesce(c.name, c.code, ''))
$$;

CREATE OR REPLACE FUNCTION public.ent_get_or_create_direct_chat(p_other_user uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_me uuid := public.ent_auth_uid();
    v_a uuid;
    v_b uuid;
    v_conversation uuid;
BEGIN
    IF v_me IS NULL OR p_other_user IS NULL OR p_other_user = v_me THEN
        RAISE EXCEPTION 'refused: choose another active staff member'
            USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.staff_profiles
         WHERE id = v_me AND is_active
    ) OR NOT EXISTS (
        SELECT 1 FROM public.staff_profiles
         WHERE id = p_other_user AND is_active
    ) THEN
        RAISE EXCEPTION 'refused: both chat participants must be active staff'
            USING ERRCODE = '42501';
    END IF;

    IF v_me < p_other_user THEN
        v_a := v_me;
        v_b := p_other_user;
    ELSE
        v_a := p_other_user;
        v_b := v_me;
    END IF;

    INSERT INTO public.staff_conversations
        (kind, direct_user_a, direct_user_b, created_by)
    VALUES ('direct', v_a, v_b, v_me)
    ON CONFLICT (direct_user_a, direct_user_b) WHERE kind = 'direct'
    DO NOTHING
    RETURNING id INTO v_conversation;

    IF v_conversation IS NULL THEN
        SELECT id INTO v_conversation
          FROM public.staff_conversations
         WHERE kind = 'direct'
           AND direct_user_a = v_a
           AND direct_user_b = v_b;
    END IF;

    INSERT INTO public.staff_conversation_members (conversation_id, user_id)
    VALUES (v_conversation, v_a), (v_conversation, v_b)
    ON CONFLICT (conversation_id, user_id) DO NOTHING;

    RETURN v_conversation;
END;
$$;

CREATE OR REPLACE FUNCTION public.ent_my_chat_conversations()
RETURNS TABLE (
    conversation_id uuid,
    kind text,
    title text,
    peer_id uuid,
    peer_role text,
    peer_clinic text,
    last_message text,
    last_message_at timestamptz,
    unread_count bigint
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT c.id,
           c.kind,
           CASE WHEN c.kind = 'clinic'
                THEN coalesce(nullif(btrim(cl.name), ''), cl.code, 'Clinic') || ' team'
                ELSE coalesce(nullif(btrim(peer.full_name), ''), 'Clinic staff')
           END,
           peer.id,
           peer.role::text,
           peer_clinic.name,
           latest.body,
           c.last_message_at,
           (SELECT count(*)
              FROM public.staff_chat_messages unread
             WHERE unread.conversation_id = c.id
               AND unread.sender_id <> public.ent_auth_uid()
               AND unread.created_at > mine.last_read_at)
      FROM public.staff_conversation_members mine
      JOIN public.staff_conversations c ON c.id = mine.conversation_id
      JOIN public.staff_profiles me ON me.id = mine.user_id AND me.is_active
      LEFT JOIN public.clinics cl ON cl.id = c.clinic_id
      LEFT JOIN public.staff_profiles peer
        ON c.kind = 'direct'
       AND peer.id = CASE WHEN c.direct_user_a = me.id THEN c.direct_user_b ELSE c.direct_user_a END
      LEFT JOIN public.clinics peer_clinic ON peer_clinic.id = peer.clinic_id
      LEFT JOIN LATERAL (
          SELECT m.body
            FROM public.staff_chat_messages m
           WHERE m.conversation_id = c.id
           ORDER BY m.created_at DESC
           LIMIT 1
      ) latest ON true
     WHERE mine.user_id = public.ent_auth_uid()
     ORDER BY c.last_message_at DESC
     LIMIT 100;
$$;

CREATE OR REPLACE FUNCTION public.ent_mark_chat_read(p_conversation_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    UPDATE public.staff_conversation_members
       SET last_read_at = now()
     WHERE conversation_id = p_conversation_id
       AND user_id = public.ent_auth_uid()
       AND EXISTS (
           SELECT 1 FROM public.staff_profiles p
            WHERE p.id = public.ent_auth_uid() AND p.is_active
       );
    IF NOT FOUND THEN
        RAISE EXCEPTION 'refused: conversation is unavailable'
            USING ERRCODE = '42501';
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.ent_mark_notifications_read(p_notification_id uuid DEFAULT NULL)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    UPDATE public.app_notifications
       SET read_at = coalesce(read_at, now())
     WHERE recipient_id = public.ent_auth_uid()
       AND (p_notification_id IS NULL OR id = p_notification_id)
       AND EXISTS (
           SELECT 1 FROM public.staff_profiles p
            WHERE p.id = public.ent_auth_uid() AND p.is_active
       )
       AND read_at IS NULL;
END;
$$;

CREATE OR REPLACE FUNCTION public.ent_unread_notification_count()
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT count(*)
      FROM public.app_notifications n
     WHERE n.recipient_id = public.ent_auth_uid()
       AND EXISTS (
           SELECT 1 FROM public.staff_profiles p
            WHERE p.id = public.ent_auth_uid() AND p.is_active
       )
       AND n.read_at IS NULL;
$$;

-- A clinic group is provisioned once and its active membership follows the
-- authoritative staff_profiles clinic assignment.
CREATE OR REPLACE FUNCTION public.ent_ensure_clinic_chat(p_clinic_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_id uuid;
BEGIN
    INSERT INTO public.staff_conversations (kind, clinic_id)
    VALUES ('clinic', p_clinic_id)
    ON CONFLICT (clinic_id) WHERE kind = 'clinic' DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
        SELECT id INTO v_id
          FROM public.staff_conversations
         WHERE kind = 'clinic' AND clinic_id = p_clinic_id;
    END IF;
    RETURN v_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.ent_sync_clinic_chat_membership()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_conversation uuid;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF OLD.clinic_id IS DISTINCT FROM NEW.clinic_id
           OR (OLD.is_active AND NOT NEW.is_active) THEN
            DELETE FROM public.staff_conversation_members m
             USING public.staff_conversations c
             WHERE m.conversation_id = c.id
               AND m.user_id = NEW.id
               AND c.kind = 'clinic'
               AND c.clinic_id = OLD.clinic_id;
        END IF;
    END IF;

    IF NEW.is_active THEN
        v_conversation := public.ent_ensure_clinic_chat(NEW.clinic_id);
        INSERT INTO public.staff_conversation_members (conversation_id, user_id)
        VALUES (v_conversation, NEW.id)
        ON CONFLICT (conversation_id, user_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_staff_chat_membership ON public.staff_profiles;
CREATE TRIGGER trg_staff_chat_membership
    AFTER INSERT OR UPDATE OF clinic_id, is_active ON public.staff_profiles
    FOR EACH ROW EXECUTE FUNCTION public.ent_sync_clinic_chat_membership();

CREATE OR REPLACE FUNCTION public.ent_create_clinic_chat()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    PERFORM public.ent_ensure_clinic_chat(NEW.id);
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_create_clinic_chat ON public.clinics;
CREATE TRIGGER trg_create_clinic_chat
    AFTER INSERT ON public.clinics
    FOR EACH ROW EXECUTE FUNCTION public.ent_create_clinic_chat();

-- Backfill one group and membership for existing clinics and active staff.
DO $$
DECLARE
    c record;
    p record;
    v_conversation uuid;
BEGIN
    FOR c IN SELECT id FROM public.clinics LOOP
        v_conversation := public.ent_ensure_clinic_chat(c.id);
        FOR p IN SELECT id FROM public.staff_profiles
                  WHERE clinic_id = c.id AND is_active LOOP
            INSERT INTO public.staff_conversation_members (conversation_id, user_id)
            VALUES (v_conversation, p.id)
            ON CONFLICT (conversation_id, user_id) DO NOTHING;
        END LOOP;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION public.ent_stamp_chat_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    me public.staff_profiles;
BEGIN
    SELECT * INTO me
      FROM public.staff_profiles
     WHERE id = public.ent_auth_uid() AND is_active;
    IF me.id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.staff_conversation_members m
         WHERE m.conversation_id = NEW.conversation_id AND m.user_id = me.id
    ) THEN
        RAISE EXCEPTION 'refused: active conversation membership required'
            USING ERRCODE = '42501';
    END IF;
    NEW.sender_id := me.id;
    NEW.sender_name := coalesce(nullif(btrim(me.full_name), ''), me.username::text);
    NEW.created_at := now();
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_stamp_chat_message ON public.staff_chat_messages;
CREATE TRIGGER trg_stamp_chat_message
    BEFORE INSERT ON public.staff_chat_messages
    FOR EACH ROW EXECUTE FUNCTION public.ent_stamp_chat_message();

CREATE OR REPLACE FUNCTION public.ent_notify_chat_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_kind text;
BEGIN
    UPDATE public.staff_conversations
       SET last_message_at = NEW.created_at
     WHERE id = NEW.conversation_id;

    SELECT kind INTO v_kind
      FROM public.staff_conversations
     WHERE id = NEW.conversation_id;

    INSERT INTO public.app_notifications
        (recipient_id, kind, title, body, target_url, source_id)
    SELECT m.user_id, 'chat_message',
           CASE WHEN v_kind = 'clinic' THEN 'New clinic message' ELSE 'New direct message' END,
           NEW.sender_name || ' sent a message.',
           'pages/messages.html?conversation=' || NEW.conversation_id::text,
           NEW.id
      FROM public.staff_conversation_members m
      JOIN public.staff_profiles p ON p.id = m.user_id AND p.is_active
     WHERE m.conversation_id = NEW.conversation_id
       AND m.user_id <> NEW.sender_id;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_chat_message ON public.staff_chat_messages;
CREATE TRIGGER trg_notify_chat_message
    AFTER INSERT ON public.staff_chat_messages
    FOR EACH ROW EXECUTE FUNCTION public.ent_notify_chat_message();

CREATE OR REPLACE FUNCTION public.ent_notify_access_request()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    INSERT INTO public.app_notifications
        (recipient_id, kind, title, body, target_url, source_id)
    SELECT p.id, 'access_request', 'Access request needs review',
           'A clinic is requesting access to a report.',
           'pages/viewAll.html', NEW.id
      FROM public.reports r
      JOIN public.staff_profiles p
        ON p.is_active
       AND (p.clinic_id = r.clinic_id OR (p.role = 'doctor' AND p.id = r.doctor_id))
     WHERE r.id = NEW.report_id
       AND p.id <> NEW.requester_id;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_access_request ON public.report_access_requests;
CREATE TRIGGER trg_notify_access_request
    AFTER INSERT ON public.report_access_requests
    FOR EACH ROW EXECUTE FUNCTION public.ent_notify_access_request();

CREATE OR REPLACE FUNCTION public.ent_notify_access_decision()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF OLD.status = 'pending' AND NEW.status IN ('approved', 'denied') THEN
        INSERT INTO public.app_notifications
            (recipient_id, kind, title, body, target_url, source_id)
        VALUES (
            NEW.requester_id,
            'access_decision',
            CASE WHEN NEW.status = 'approved' THEN 'Access request approved' ELSE 'Access request denied' END,
            CASE WHEN NEW.status = 'approved'
                 THEN 'The owning clinic approved your request.'
                 ELSE 'The owning clinic declined your request.' END,
            'pages/viewAll.html',
            NEW.id
        );
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_access_decision ON public.report_access_requests;
CREATE TRIGGER trg_notify_access_decision
    AFTER UPDATE OF status ON public.report_access_requests
    FOR EACH ROW EXECUTE FUNCTION public.ent_notify_access_decision();

CREATE OR REPLACE FUNCTION public.ent_notify_ticket_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    INSERT INTO public.app_notifications
        (recipient_id, kind, title, body, target_url, source_id)
    SELECT p.id, 'ticket_new', 'New clinic support ticket',
           'A staff member submitted a support ticket.',
           'pages/admin.html#panel-tickets', NEW.id
      FROM public.staff_profiles p
     WHERE p.clinic_id = NEW.clinic_id
       AND p.is_active AND p.role = 'admin'
       AND p.id <> NEW.created_by;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_ticket_insert ON public.tickets;
CREATE TRIGGER trg_notify_ticket_insert
    AFTER INSERT ON public.tickets
    FOR EACH ROW EXECUTE FUNCTION public.ent_notify_ticket_insert();

CREATE OR REPLACE FUNCTION public.ent_notify_ticket_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    INSERT INTO public.app_notifications
        (recipient_id, kind, title, body, target_url, source_id)
    SELECT recipients.user_id, 'ticket_message', 'Support ticket updated',
           'A support ticket has a new reply.',
           CASE WHEN recipients.is_admin THEN 'pages/admin.html#panel-tickets' ELSE 'pages/reportProblem.html' END,
           NEW.id
      FROM (
          SELECT t.created_by AS user_id, false AS is_admin
            FROM public.tickets t
           WHERE t.id = NEW.ticket_id AND t.created_by <> NEW.author_id
          UNION
          SELECT p.id, true
            FROM public.tickets t
            JOIN public.staff_profiles p
              ON p.clinic_id = t.clinic_id AND p.is_active AND p.role = 'admin'
           WHERE t.id = NEW.ticket_id AND p.id <> NEW.author_id
      ) recipients;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_ticket_message ON public.ticket_messages;
CREATE TRIGGER trg_notify_ticket_message
    AFTER INSERT ON public.ticket_messages
    FOR EACH ROW EXECUTE FUNCTION public.ent_notify_ticket_message();

CREATE OR REPLACE FUNCTION public.ent_notify_ticket_status()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO public.app_notifications
            (recipient_id, kind, title, body, target_url, source_id)
        VALUES (
            NEW.created_by, 'ticket_status', 'Support ticket status changed',
            'Your support ticket status is now ' || replace(NEW.status::text, '_', ' ') || '.',
            'pages/reportProblem.html', NEW.id
        );
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_ticket_status ON public.tickets;
CREATE TRIGGER trg_notify_ticket_status
    AFTER UPDATE OF status ON public.tickets
    FOR EACH ROW EXECUTE FUNCTION public.ent_notify_ticket_status();

-- Only trusted trigger functions write notifications. Chat messages are
-- append-only; identity and timestamps are server-stamped on insertion.
REVOKE ALL ON public.app_notifications FROM anon, public;
GRANT SELECT ON public.app_notifications TO authenticated;
GRANT ALL ON public.app_notifications TO service_role;

REVOKE ALL ON public.staff_conversations FROM anon, public;
GRANT SELECT ON public.staff_conversations TO authenticated;
GRANT ALL ON public.staff_conversations TO service_role;

REVOKE ALL ON public.staff_conversation_members FROM anon, public;
GRANT SELECT ON public.staff_conversation_members TO authenticated;
GRANT ALL ON public.staff_conversation_members TO service_role;

REVOKE ALL ON public.staff_chat_messages FROM anon, public;
GRANT SELECT, INSERT ON public.staff_chat_messages TO authenticated;
GRANT ALL ON public.staff_chat_messages TO service_role;

REVOKE ALL ON FUNCTION public.ent_search_chat_staff(text) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.ent_search_chat_staff(text) TO authenticated;
REVOKE ALL ON FUNCTION public.ent_chat_staff_directory(text) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.ent_chat_staff_directory(text) TO authenticated;
REVOKE ALL ON FUNCTION public.ent_get_or_create_direct_chat(uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.ent_get_or_create_direct_chat(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.ent_my_chat_conversations() FROM anon, public;
GRANT EXECUTE ON FUNCTION public.ent_my_chat_conversations() TO authenticated;
REVOKE ALL ON FUNCTION public.ent_mark_chat_read(uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.ent_mark_chat_read(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.ent_mark_notifications_read(uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.ent_mark_notifications_read(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.ent_unread_notification_count() FROM anon, public;
GRANT EXECUTE ON FUNCTION public.ent_unread_notification_count() TO authenticated;
REVOKE ALL ON FUNCTION public.ent_ensure_clinic_chat(uuid) FROM anon, public, authenticated;
GRANT EXECUTE ON FUNCTION public.ent_ensure_clinic_chat(uuid) TO service_role;
REVOKE ALL ON FUNCTION public.ent_sync_clinic_chat_membership() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_create_clinic_chat() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_stamp_chat_message() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_notify_chat_message() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_notify_access_request() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_notify_access_decision() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_notify_ticket_insert() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_notify_ticket_message() FROM anon, public, authenticated;
REVOKE ALL ON FUNCTION public.ent_notify_ticket_status() FROM anon, public, authenticated;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
        IF NOT EXISTS (
            SELECT 1 FROM pg_publication_tables
             WHERE pubname = 'supabase_realtime'
               AND schemaname = 'public'
               AND tablename = 'app_notifications'
        ) THEN
            ALTER PUBLICATION supabase_realtime ADD TABLE public.app_notifications;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM pg_publication_tables
             WHERE pubname = 'supabase_realtime'
               AND schemaname = 'public'
               AND tablename = 'staff_chat_messages'
        ) THEN
            ALTER PUBLICATION supabase_realtime ADD TABLE public.staff_chat_messages;
        END IF;
    END IF;
END;
$$;

NOTIFY pgrst, 'reload schema';
